use crate::*;
use crate::{NativeDefault,NativeDefaultCursor};
struct Bank{g:RetainedCloneGrant,fuel:u64,maximum:u64,work:u64}
impl Bank{fn new()->Self{let law:serde_json::Value=serde_json::from_str(include_str!("../📐️.json")).unwrap();let s=&law["stock"];Self{g:RetainedCloneGrant{maximum_items:s["items"].as_u64().unwrap()as usize,maximum_copy_bytes:s["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:s["capacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:s["releaseBytes"].as_u64().unwrap()as usize,maximum_depth:s["depth"].as_u64().unwrap()as usize},fuel:s["fuel"].as_u64().unwrap(),maximum:s["maximumTurns"].as_u64().unwrap(),work:0}}fn offer(&self)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:self.g.maximum_items.min(1),..self.g}}fn post(&mut self,p:RetainedCloneProgress,work:u64){assert!(p.fits(self.g));assert!(work<=1);self.g.maximum_items-=p.copied_items;self.g.maximum_copy_bytes-=p.copied_bytes;self.g.maximum_capacity_bytes-=p.retained_capacity_bytes;self.g.maximum_release_bytes-=p.released_bytes;self.fuel=self.fuel.checked_sub(work).unwrap();self.work+=work;}fn retire<T:RetireOwned>(&mut self,value:T){let mut owner=crate::retirement::controlled::ControlledRetirement::new(value).map_err(|(e,_)|e).unwrap();for _ in 0..self.maximum{if owner.terminal_is_empty(){break}let(s,heap)=crate::observe_retirement_allocations(||owner.step(self.offer()).unwrap());let p=s.progress();assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));self.post(p,owner.last_turn_work());}assert!(owner.terminal_is_empty());}}
fn run<T:NativeDefault>(cut:Option<u64>,check:impl FnOnce(&T))->u64{let mut bank=Bank::new();let(mut cursor,heap)=crate::observe_retirement_allocations(T::default_cursor);assert_eq!(heap,(0,0));let mut callback=|_|true;let mut control=NativeDecodeControl::new(bank.g.maximum_capacity_bytes,&mut callback);let mut null_seen=false;for _ in 0..cut.unwrap_or(bank.maximum){if cursor.output_ready(){break}let d=cursor.demands(4096).unwrap();let g=bank.offer();for denied in[Some(RetainedCloneGrant{maximum_items:0,..g}),(d.copy_bytes>0).then_some(RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes.saturating_sub(1),..g}),(d.capacity_bytes>0).then_some(RetainedCloneGrant{maximum_capacity_bytes:d.capacity_bytes.saturating_sub(1),..g}),(d.depth>0).then_some(RetainedCloneGrant{maximum_depth:d.depth.saturating_sub(1),..g})].into_iter().flatten(){let(turn,heap)=crate::observe_retirement_allocations(||cursor.advance(&mut control,4096,denied));assert_eq!(turn.work,0);assert_eq!(turn.result.unwrap().progress(),Default::default());assert_eq!(heap,(0,0));}if d.capacity_bytes>0&&!null_seen{let((turn,attempts),heap)=crate::observe_retirement_allocations(||semio_framework_value_testing_allocator::refuse_one_allocation_on_this_thread(||cursor.advance(&mut control,4096,g)));assert_eq!(attempts,1);assert_eq!(heap,(0,0));assert_eq!(turn.work,1);let p=turn.result.as_ref().err().unwrap().retained_progress();bank.post(p,turn.work);bank.retire(turn.result.err().unwrap());null_seen=true;continue}let(turn,heap)=crate::observe_retirement_allocations(||cursor.advance(&mut control,4096,g));let p=turn.result.unwrap().progress();assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));bank.post(p,turn.work);}let normal_work=bank.work;if cut.is_none(){assert!(cursor.output_ready());let(turn,heap)=crate::observe_retirement_allocations(||cursor.take(bank.offer()));let(output,p)=turn.result.unwrap().unwrap();assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));bank.post(p,turn.work);check(&output);bank.retire(output);}cursor.begin_close();for _ in 0..bank.maximum{if cursor.terminal_is_empty(){break}let(turn,heap)=crate::observe_retirement_allocations(||cursor.close_step(bank.offer()));let p=turn.result.unwrap().progress();assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));bank.post(p,turn.work);}assert!(cursor.terminal_is_empty());assert_eq!(cursor.close_step(Default::default()).work,0);normal_work}
#[test]fn actual_native_default_array_and_tuple_are_owned_phased_and_match_independent_serde(){let law:serde_json::Value=serde_json::from_str(include_str!("../📐️.json")).unwrap();run::<[f64;3]>(None,|v|assert_eq!(serde_json::to_value(v).unwrap(),law["smallArray"]));run::<(String,bool)>(None,|v|assert_eq!(serde_json::to_value(v).unwrap(),law["tuple"]));for cut in law["cancelCuts"].as_array().unwrap(){run::<[String;3]>(Some(cut.as_u64().unwrap()),|_|{});}}
#[test]fn actual_native_default_large_zero_sized_array_cannot_collapse_into_one_cpu_turn(){let law:serde_json::Value=serde_json::from_str(include_str!("../📐️.json")).unwrap();let work=run::<[();4097]>(None,|v|{assert_eq!(v.len(),law["largeZeroSizedCount"].as_u64().unwrap()as usize);assert_eq!(serde_json::to_value(v.iter().collect::<Vec<_>>()).unwrap(),serde_json::json!(vec![serde_json::Value::Null;4097]));});assert!(work>=law["minimumLargeWork"].as_u64().unwrap());}
#[test]fn actual_native_empty_array_default_keeps_its_original_refusal(){let mut cursor=<[u8;0]as NativeDefault>::default_cursor();let mut callback=|_|true;let mut control=NativeDecodeControl::new(0,&mut callback);let turn=cursor.advance(&mut control,4096,RetainedCloneGrant{maximum_items:1,maximum_depth:64,..Default::default()});assert_eq!(turn.work,1);assert!(turn.result.is_err());assert!(!cursor.output_ready());cursor.begin_close();assert!(cursor.terminal_is_empty());}

#[test]fn actual_default_leaf_payload_writes_differ_from_empty_owner_headers(){let law:serde_json::Value=serde_json::from_str(include_str!("../📐️.json")).unwrap();let mut bank=Bank::new();let mut callback=|_|true;let mut control=NativeDecodeControl::new(bank.g.maximum_capacity_bytes,&mut callback);macro_rules! check{($ty:ty,$kind:literal,$expected:expr)=>{{let mut cursor=<$ty as NativeDefault>::default_cursor();let d=cursor.demands(4096).unwrap();assert_eq!(d.copy_bytes,law["freshPayloadCopyBytes"][$kind].as_u64().unwrap()as usize);if d.copy_bytes>0{let(turn,heap)=crate::observe_retirement_allocations(||cursor.advance(&mut control,4096,RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes-1,..bank.offer()}));assert_eq!(turn.work,0);assert_eq!(turn.result.unwrap().progress(),Default::default());assert_eq!(heap,(0,0));assert!(!cursor.output_ready());}let(turn,heap)=crate::observe_retirement_allocations(||cursor.advance(&mut control,4096,bank.offer()));assert_eq!(turn.work,1);let p=turn.result.unwrap().progress();assert_eq!(p.copied_bytes,d.copy_bytes);assert_eq!(heap,(0,0));bank.post(p,turn.work);let turn=cursor.take(bank.offer());let(value,p)=turn.result.unwrap().unwrap();bank.post(p,turn.work);assert_eq!(value,$expected);bank.retire(value);cursor.begin_close();assert!(cursor.terminal_is_empty());}};}check!(bool,"bool",false);check!(u64,"u64",0);check!(f64,"f64",0.0);check!(String,"string",String::new());check!((),"unit",());}
